def reverse_words(text):
    words = []
    current_word = []

    for char in text:
        if char == ' ':
            if current_word:
                words.append(''.join(current_word[::-1]))
                current_word = []
            words.append(' ')
        else:
            current_word.append(char)

    if current_word:
        words.append(''.join(current_word[::-1]))

    return ''.join(words)
